	    		WHERE PERIODSEQ = i_periodSeq
	    		-- EARNINGGROUPID = '01-RG'
	    		AND PRODUCTID LIKE '01%' AND PRODUCTID NOT LIKE '012%'
	    		-- EARNINGCODEID = '101'
	    		AND (EVENTTYPEID IN ('81','20')
