            AND EVENTTYPEID = '10';
            
    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'TEMP_BASES_112_03_RT (BALANCE): ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
