                      		--ORDER BY T.ORDERID
                      ) AS RN_TRX
			FROM :TEMP_FINAL_PAGOS_BASES_123_126_127_01_RG T
			WHERE 1 = (CASE 
					WHEN (T.IMPORTE_PAGO - IFNULL(T.SUMA_IMPORTE,0)) = 0 THEN 0
					WHEN (T.IMPORTE_PAGO - IFNULL(T.SUMA_IMPORTE,0)) BETWEEN -2 AND 2 THEN 1
