    	--FINAL
    	TEMP_FINAL_PAGOS_BASES_124_125_01_RT = SELECT P.PARTICIPANTSEQ,
                                P.POSITIONSEQ,
                                P.PERIODSEQ,
                                :v_periodName AS PERIODO,
                                P.POS_CALLIDUS POSITIONNAME,
                                P.POS_PRIN,
