                                PRIMA_NETA,
                                PRIMA_NETA_ANUAL,
                                PRIMA_COMIS_S4 PRIMA_COMIS,
                                NULL AS COEF_TIPO_BASE,
                                NULL AS COEF_CORRECTOR,
                                COD_AGENTE,
                                P.TIPO_LIQ
    					FROM :TEMP_PAGOS_DIRECTOS_124_125_01_RT P
