		        ,TF."EARNINGCODEID",TF.SUMA_IMPORTE,"DEPOSITSEQ",TF."DEPOSITO","TIPO_PAGO","PROGRAMA","ESTADO","COMPENSATIONDATE","CODIGO_POLIZA","PRODUCTID","EVENTTYPEID","SUBLINENUMBER"
