	    		-- EARNINGGROUPID = '01-RT'
	    		-- AND PRODUCTID LIKE '032%'
	    		-- EARNINGCODEID = '15'
	    		AND EVENTTYPEID = 'Pago Comercial';
	    		
	    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'TEMP_BASES_1_MAC38P03_RT (BALANCE):' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
