    	TEMP_FINAL_PAGOS_BASES_1_MAC38P03_RT = SELECT P.PARTICIPANTSEQ,
                                P.POSITIONSEQ,
                                P.PERIODSEQ,
                                :v_periodName AS PERIODO,
                                P.POS_CALLIDUS POSITIONNAME,
