    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'TEMP_FINAL_PAGOS_BASES_1_MAC38P03_RT: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');
    	
