                                P.EARNINGCODEID,
                                P.EARNINGGROUPID,
                                P.TIPO_DOCUMENTO,
                                P.TIPO_AGENTE,
                                B.IMPORTE_COMISION AS IMPORTE,
                                (SELECT SUM(IMPORTE_COMISION)
