    	TEMP_FINAL_PAGOS_BASES_2_82_03_RT = SELECT P.PARTICIPANTSEQ,
                                P.POSITIONSEQ,
                                P.PERIODSEQ,
                                :v_periodName AS PERIODO,
                                P.POS_CALLIDUS POSITIONNAME,
                                P.POS_PRIN,
                                P.NIF,
                                P.MANAGER_POS_PRIN,
