                                LINENUMBER,
                                SUBLINENUMBER,
                                EVENTTYPEID,
                                PRODUCTID,
                                CODIGO_POLIZA,
                                COMPENSATIONDATE,
                                ESTADO,
                                P.PROGRAMA,
                                P.TIPO_PAGO,
                                P.DEPOSITO,
                                P.DEPOSITSEQ,
                                P.IMPORTE IMPORTE_PAGO,
                                P.EARNINGCODEID,
                                P.EARNINGGROUPID,
                                P.TIPO_DOCUMENTO,
                                P.TIPO_AGENTE,
