					WHEN (T.IMPORTE_PAGO - IFNULL(T.SUMA_IMPORTE,0)) BETWEEN -2 AND 2 THEN 1
					ELSE 0 
				END)
	--		AND F.EARNINGCODEID = T.EARNINGCODEID AND F.EARNINGGROUPID = T.EARNINGGROUPID
			;
