				FROM :TEMP_FINAL_PAGOS_BASES_5_03_RG_MACB38P
				WHERE TIPO_LIQ IN ('CIERRE','LIQ')
				GROUP BY PERIODSEQ,POS_PRIN,EARNINGGROUPID,EARNINGCODEID,DEPOSITO;
		
