		    	AND TF.EARNINGGROUPID = TLC.EARNINGGROUPID AND TF.EARNINGCODEID = TLC. EARNINGCODEID AND TF.DEPOSITO = TLC.DEPOSITO
		    	AND 1 = (CASE WHEN SUMA_PAGOS <> SUMA_IMPORTE THEN 1 END); 
