                                P.DEPOSITO,
                                P.DEPOSITSEQ,
                                P.IMPORTE IMPORTE_PAGO,
                                P.EARNINGCODEID,
                                P.EARNINGGROUPID,
                                P.TIPO_DOCUMENTO,
                                P.TIPO_AGENTE,
                                B.IMPORTE_COMISION AS IMPORTE,
                                -- SUM(B.IMPORTE_COMISION) OVER(PARTITION BY P.POSITIONSEQ) AS SUMA_IMPORTE,
                                (SELECT SUM(IMPORTE_COMISION)
