         --                               AND X.TIPO_DOCUMENTO = P.TIPO_DOCUMENTO )
    					

 						AND NOT EXISTS (
							SELECT 1
							FROM EXT.FINAL_REPEXT_FILE_TEST X 
								WHERE X.POS_PRIN       = P.POS_PRIN
									AND X.PERIODSEQ      = P.PERIODSEQ
									AND X.EARNINGCODEID  = P.EARNINGCODEID
									AND X.EARNINGGROUPID = P.EARNINGGROUPID
									AND X.TIPO_DOCUMENTO = P.TIPO_DOCUMENTO
