									AND X.SUBLINENUMBER  = B.SUBLINENUMBER
									AND X.EVENTTYPEID    = B.EVENTTYPEID
							)
    					
    					;
    	CALL LIB_GLOBAL:WRITE_LOG (v_permisos_log, v_proc_name,'TEMP_FINAL_PAGOS_BASES_5_82_RT: ' || ::ROWCOUNT, v_log_count, v_idproceso, 'info');	
    	
    
    	
