			AND F.TIPO_DOCUMENTO = T.TIPO_DOCUMENTO AND F.DEPOSITSEQ = T.DEPOSITSEQ
			WHERE 1 = (CASE 
    				WHEN (T.IMPORTE_PAGO - IFNULL(T.SUMA_IMPORTE,0)) = 0 THEN 1
					WHEN (T.IMPORTE_PAGO - IFNULL(T.SUMA_IMPORTE,0)) BETWEEN -2 AND 2 THEN 1
					ELSE 0 
