	    ELSE
	    	TEMP_BASES_5_RT = SELECT * 
    		FROM EXT.FINAL_BASES_REPARTO_POLIZA_FILE_NUEVA_BASE_REPARTO B
    		WHERE PERIODSEQ = v_periodSeqAnterior
    		--RAMO EARNINGGROUPID = '03-RT'
    		--AND PRODUCTID LIKE '032%'
